"""Run this once from C:\Claude\FoldPad to generate launcher icon PNGs.
Open a terminal in that folder and run: python gen_icons.py
"""
import base64, os

icons = {
    "mipmap-mdpi":    "",
    "mipmap-hdpi":    "",
    "mipmap-xhdpi":   "",
    "mipmap-xxhdpi":  "",
    "mipmap-xxxhdpi": "",
}

base_path = os.path.dirname(os.path.abspath(__file__))
res_path  = os.path.join(base_path, "app", "src", "main", "res")

for folder, b64 in icons.items():
    target = os.path.join(res_path, folder)
    os.makedirs(target, exist_ok=True)
    data = base64.b64decode(b64)
    for name in ["ic_launcher.png", "ic_launcher_round.png"]:
        with open(os.path.join(target, name), "wb") as f:
            f.write(data)
        print(f"  wrote {folder}/{name}")

print("Done.")
